import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

import {
  managedHostRunDirectory,
  readManagedReviewImportSeal,
  managedHostRunReceipt,
  readManagedHostRunBinding,
  readManagedReviewEvidenceProposal,
  type ManagedHostRunReceipt,
  type ManagedReviewEvidenceProposal,
} from './managed-host-run.js';
import { isStrictManagedReviewFindingProposal } from './host-run.js';
import { loadConfig } from './config.js';
import { resolvePromptRoleBody } from './prompt-role-contract-registry.js';
import {
  buildProofAdmissibilityDiagnostic,
  type ProofAdmissibilityDiagnostic,
} from './proof-admissibility-gates.js';
import type { Finding, ManagedReviewEvidenceBinding, ReviewPass, ReviewRun } from './types.js';
import { digestCanonicalJson } from './digest.js';

export interface ManagedReviewEvidenceVerification {
  valid: boolean;
  reason: string;
  diagnostic: ProofAdmissibilityDiagnostic;
  receipt: ManagedHostRunReceipt | null;
  proposal: ManagedReviewEvidenceProposal | null;
}

function sha256(text: string): string {
  return `sha256:${createHash('sha256').update(text, 'utf8').digest('hex')}`;
}

function rawSha256(text: string): string {
  return createHash('sha256').update(text, 'utf8').digest('hex');
}

export interface ManagedReviewExpectedBinding {
  providerHost: 'codex' | 'claude' | 'agy';
  headHash: string;
  materialHash: string;
  storyFilesHash: string;
  promptHash: string;
  envelopeId: string | null;
  managedPromptDigest: string;
}

export type ReviewerExecutionAuthorityClassification =
  | 'managed-cross-provider-receipt'
  | 'native-host-signed-review'
  | 'degraded-single-host-local-only'
  | 'cross-provider-advisory-only';

export interface ReviewerExecutionAuthority {
  classification: ReviewerExecutionAuthorityClassification;
  directSignedReviewAllowed: boolean;
  managedReceiptRequired: boolean;
  reviewGatePath: 'managed-receipt' | 'direct-signed-review' | 'local-host-verdict-only' | 'none';
}

/**
 * Keep native-host, managed cross-provider, and explicit degraded assurance
 * semantically disjoint. A managed receipt is the only cross-provider CLI path
 * into REVIEW evidence; degraded single-host evidence remains a local DONE
 * assurance fact and never borrows either reviewer authority path.
 */
export function classifyReviewerExecutionAuthority(args: {
  executionMode: 'native-host' | 'cross-provider-cli';
  assuranceLevel: 'ordinary-review' | 'degraded-single-host';
  hasManagedEvidenceBinding: boolean;
}): ReviewerExecutionAuthority {
  if (args.assuranceLevel === 'degraded-single-host') {
    return {
      classification: 'degraded-single-host-local-only',
      directSignedReviewAllowed: false,
      managedReceiptRequired: false,
      reviewGatePath: 'local-host-verdict-only',
    };
  }
  if (args.executionMode === 'cross-provider-cli') {
    return args.hasManagedEvidenceBinding
      ? {
        classification: 'managed-cross-provider-receipt',
        directSignedReviewAllowed: false,
        managedReceiptRequired: true,
        reviewGatePath: 'managed-receipt',
      }
      : {
        classification: 'cross-provider-advisory-only',
        directSignedReviewAllowed: false,
        managedReceiptRequired: true,
        reviewGatePath: 'none',
      };
  }
  if (args.hasManagedEvidenceBinding) {
    return {
      classification: 'cross-provider-advisory-only',
      directSignedReviewAllowed: false,
      managedReceiptRequired: true,
      reviewGatePath: 'none',
    };
  }
  return {
    classification: 'native-host-signed-review',
    directSignedReviewAllowed: true,
    managedReceiptRequired: false,
    reviewGatePath: 'direct-signed-review',
  };
}

export function resolveManagedReviewerBasePrompt(root: string, run: ReviewRun): string {
  if (run.assembledPrompt) return run.assembledPrompt;
  const body = resolvePromptRoleBody(run.lane, loadConfig(root).promptEnvelope).body;
  if (rawSha256(body) !== run.promptHash) {
    throw new Error('managed reviewer: legacy ReviewRun prompt hash does not match the canonical role body');
  }
  return body;
}

export function buildManagedReviewerPrompt(root: string, run: ReviewRun): string {
  const binding = JSON.stringify({
    storyId: run.storyId,
    providerAgent: run.lane,
    lane: run.lane,
    reviewRunId: run.reviewRunId,
  });
  return [
    '--- BEGIN MANAGED REVIEW EVIDENCE PROTOCOL ---',
    `This provider run is already bound to ${binding}.`,
    'This managed protocol overrides any generic reviewer-role instruction to register a pass or finding directly. Do not call review_run_start, review_pass_set, or finding_add in this run.',
    'Your final assistant result MUST contain exactly one JSON object and no prose, tool call, or markdown fence. Do not call managed_review_proposal_set; tool-shell output is not formal evidence.',
    'Use schemaVersion="lattice.managed_review_final_proposal.v1" and the exact bound fields above. For a pass add conclusion="pass", note, and truthful readManifest/readLog. For findings add conclusion="findings", exact findings, and truthful read evidence.',
    'The managed host adapter reads only this bounded final assistant result after provider exit, seals the exact verdict, and then permits receipt import. The controller cannot substitute or override it.',
    '--- END MANAGED REVIEW EVIDENCE PROTOCOL ---',
    '',
    resolveManagedReviewerBasePrompt(root, run),
  ].join('\n');
}

export function managedReviewerPromptDigest(root: string, run: ReviewRun): string {
  return sha256(buildManagedReviewerPrompt(root, run));
}

function failedDiagnostic(): ProofAdmissibilityDiagnostic {
  return buildProofAdmissibilityDiagnostic({
    artifactKind: 'managed-review-evidence',
    consumer: 'REVIEW',
    claim: 'review-pass',
    mode: 'enforce',
    enforcedConsumers: ['REVIEW'],
    checks: {
      schemaVersion: 'lattice.managed_review_evidence_binding.v1',
      strictShapeValid: false,
      semanticDigestValid: false,
      signatureOrReceiptBindingValid: false,
      temporalAndMaterialBindingValid: false,
      subjectMatches: false,
      storyMatches: false,
      gatePhaseMatches: true,
      producerBoundaryTrusted: false,
    },
  });
}

export function verifyManagedReviewEvidence(args: {
  root: string;
  storyId: string;
  agent: string;
  reviewRunId: string;
  lane: string;
  binding: ManagedReviewEvidenceBinding;
  expected: ManagedReviewExpectedBinding;
  evidence?: { kind: 'pass'; pass: ReviewPass } | { kind: 'finding'; finding: Finding };
}): ManagedReviewEvidenceVerification {
  let receipt: ManagedHostRunReceipt;
  let proposal: ManagedReviewEvidenceProposal | null;
  let runBinding: ReturnType<typeof readManagedHostRunBinding>;
  try {
    receipt = managedHostRunReceipt(args.root, args.binding.runId);
    proposal = readManagedReviewEvidenceProposal(args.root, args.binding.runId);
    runBinding = readManagedHostRunBinding(args.root, args.binding.runId);
  } catch (error) {
    // B-137a:F-107 — the artifact read failed (missing/corrupt receipt,
    // proposal or run binding). The verdict stays fail-closed, but surface WHY
    // instead of discarding it: without this, a corrupt-artifact refusal and a
    // genuinely-absent-artifact refusal are indistinguishable to an operator.
    const diagnostic = failedDiagnostic();
    const cause = error instanceof Error ? error.message : String(error);
    return {
      valid: false,
      reason: `${diagnostic.reasons.join(',')} (artifact read failed: ${cause})`,
      diagnostic,
      receipt: null,
      proposal: null,
    };
  }
  const terminalPath = join(managedHostRunDirectory(args.root, args.binding.runId), 'terminal.json');
  const runDirectory = managedHostRunDirectory(args.root, args.binding.runId);
  // B-137a:F-120 — these runtime-directory reads must share the SAME fail-closed
  // guard as the artifact reads above. The F-107 fix wrapped only the receipt /
  // proposal / run-binding reads, leaving terminal.json, evidence-proposal.json,
  // spec.json, events.jsonl, result.json and the readdir unguarded: a partially
  // written or pruned run directory (pruneExpiredManagedHostRuns can delete one
  // that is later re-verified) made verification THROW instead of returning the
  // intended diagnostic refusal, so an operator saw a stack trace rather than a
  // reason code. Fail-closed is the contract for every read on this path.
  let observedTerminalDigest: string;
  let observedProposalDigest: string | null;
  let proposalArtifacts: string[];
  let observedSpecDigest: string;
  let observedEventJournalDigest: string;
  let observedResultDigest: string | null;
  // B-137a:F-127 — archive-backed recover after terminal-retention GC
  // (>= 90 days, and only via an explicit `doctor --repair`). The heavy run
  // directory is deleted; `.lattice/runtime/host-run-receipts/<runId>.json`
  // retains the sealed receipt, evidence-binding digest, binding projection,
  // provider-authored proposal body, and import-seal pair. Heavy live-output
  // and result provider text are not retained.
  //
  // The digests below are only ever compared against that same receipt's
  // digests, so when the artifacts are legitimately reclaimed the archived
  // receipt IS the authority; adopting its values preserves exactly the
  // comparison that would otherwise have been made, and the archive is
  // self-verifying (receiptId is recomputed over the archived payload). The
  // proposal and import-seal pair are recovered by their archive-backed
  // readers after digest/schema checks. While the directory exists the live
  // files are read and compared exactly as before.
  //
  // Refuse-closed: pre-F-127 archives that lack the later capture fields,
  // receipt/proposal/binding digest mismatches, archived-seal
  // schemaVersion/runId/bindingDigest mismatches, and active/corrupt/one-shot
  // runs (those are never GC'd).
  const runDirectoryReclaimed = !existsSync(join(runDirectory, 'spec.json'))
    && !existsSync(join(runDirectory, 'terminal.json'));
  if (runDirectoryReclaimed) {
    observedTerminalDigest = args.binding.terminalDigest;
    observedProposalDigest = receipt.evidenceProposalDigest;
    proposalArtifacts = receipt.evidenceProposalDigest ? ['evidence-proposal.json'] : [];
    observedSpecDigest = receipt.specDigest;
    observedEventJournalDigest = receipt.eventJournalDigest;
    observedResultDigest = receipt.resultDigest;
  } else try {
    observedTerminalDigest = sha256(readFileSync(terminalPath, 'utf8'));
    observedProposalDigest = proposal
      ? sha256(readFileSync(join(runDirectory, 'evidence-proposal.json'), 'utf8'))
      : null;
    proposalArtifacts = readdirSync(runDirectory)
      .filter(name => /^evidence-proposal(?:[.-].*)?\.json$/.test(name));
    observedSpecDigest = sha256(readFileSync(join(runDirectory, 'spec.json'), 'utf8'));
    observedEventJournalDigest = existsSync(join(runDirectory, 'events.jsonl'))
      ? sha256(readFileSync(join(runDirectory, 'events.jsonl'), 'utf8'))
      : sha256('');
    observedResultDigest = existsSync(join(runDirectory, 'result.json'))
      ? sha256(readFileSync(join(runDirectory, 'result.json'), 'utf8'))
      : null;
  } catch (error) {
    try {
      if (this.retain && this.retain(line)) {
        this.retained = line;
        // F-026: a freshly retained usage-bearing candidate supersedes any
        // earlier over-cap drop (last-usage-wins) — clear the poison so the
        // candidate is recorded honestly. Only a retained CANDIDATE clears it;
        // ordinary under-cap non-usage lines leave the flag untouched.
        this.truncatedSinceLastCandidate = false;
      }
    } catch {
      // A retain predicate must never throw; ignore a malformed line.
    }
  }

  /** The retained usage-bearing line (or '' when none was retained). */
  retainedText(): string {
    return this.retained ?? '';
  }

  /** F-026: true when an over-cap drop happened after (or without) the retained candidate. */
  get truncated(): boolean {
    return this.truncatedSinceLastCandidate;
  }
}

/**
 * Bounded, provider-specific terminal-result lane. It accepts only the
 * canonical adapter events emitted by the provider CLI and never examines
 * stderr, tool-log payloads, or arbitrary passthrough chunks as evidence.
 */
export const MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION = 'lattice.managed_review_final_proposal.v1' as const;
export const MANAGED_REVIEW_CLAUDE_JSON_SCHEMA_MAX_BYTES = 16 * 1024;

export interface ManagedReviewFinalEnvelopeReadManifest extends Record<string, unknown> {
  filesReadFully: string[];
  filesTriagedByName: string[];
  scanEscalationReason: string | null;
  candidateSpecSetDigest?: string;
  corpusDigest?: string;
}

export interface ManagedReviewFinalEnvelopeFinding extends Record<string, unknown> {
  desc: string;
  severity: 'critical' | 'high' | 'medium' | 'low';
  category: 'happy' | 'edge' | 'adversarial' | 'missing';
  files?: string[];
  evidenceState?: 'suspected' | 'verified';
  uncertaintyReason?: string;
}

export interface ManagedReviewFinalEnvelopeRecord extends Record<string, unknown> {
  schemaVersion: typeof MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION;
  storyId: string;
  providerAgent: string;
  lane: string;
  reviewRunId: string;
  conclusion: 'pass' | 'findings';
  note?: string;
  findings?: ManagedReviewFinalEnvelopeFinding[];
  readManifest: ManagedReviewFinalEnvelopeReadManifest;
}

/**
 * Claude Code's structured-output schema is necessarily a CLI argument. Keep it
 * bounded and non-secret: it contains only the already-auditable managed review
 * tuple plus public vocabulary, never prompt bytes, capabilities, or verdicts.
 */
function managedReviewClaudeJsonSchema(args: HostRunArgs): string {
  if (!args.storyId || !args.reviewRunId || !args.lane || args.agentType !== args.lane) {
    throw new Error('host_run: managed Claude JSON Schema requires exact storyId/reviewRunId/lane/agentType binding');
  }
  // Keep the provider schema inside Claude Structured Outputs' supported core
  // subset. Richer semantic constraints (non-blank text, digests, non-empty
  // findings, and pass/findings exclusivity) are still enforced by the exact
  // local envelope parser before any bytes are sealed as evidence.
  const nonBlankString = { type: 'string' };
  const stringArray = { type: 'array', items: { type: 'string' } };
  const digest = { type: 'string' };
  const readManifest = {
    type: 'object',
    additionalProperties: false,
    required: ['filesReadFully', 'filesTriagedByName', 'scanEscalationReason'],
    properties: {
      filesReadFully: stringArray,
      filesTriagedByName: stringArray,
      scanEscalationReason: { type: ['string', 'null'] },
      candidateSpecSetDigest: digest,
      corpusDigest: digest,
    },
  };
  const readLog = {
    type: 'object',
    additionalProperties: false,
    required: ['filesReadFully', 'filesTriagedByName', 'summary', 'digest'],
    properties: {
      filesReadFully: stringArray,
      filesTriagedByName: stringArray,
      summary: {
        type: 'object',
        additionalProperties: false,
        required: ['readCount', 'tokenCount'],
        properties: {
          readCount: { type: 'integer' },
          tokenCount: { type: ['integer', 'null'] },
        },
      },
      digest: { type: 'string', pattern: '^[a-f0-9]{64}$' },
    },
  };
  const finding = {
    type: 'object',
    additionalProperties: false,
    required: ['desc', 'severity', 'category'],
    properties: {
      desc: nonBlankString,
      severity: { enum: ['critical', 'high', 'medium', 'low'] },
      category: { enum: ['happy', 'edge', 'adversarial', 'missing'] },
      files: { type: 'array', items: nonBlankString },
      evidenceState: { enum: ['suspected', 'verified'] },
      uncertaintyReason: nonBlankString,
    },
  };
  const schema = {
    type: 'object',
    additionalProperties: false,
    required: ['schemaVersion', 'storyId', 'providerAgent', 'lane', 'reviewRunId', 'conclusion', 'readManifest'],
    properties: {
      schemaVersion: { const: MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION },
      storyId: { const: args.storyId },
      providerAgent: { const: args.agentType },
      lane: { const: args.lane },
      reviewRunId: { const: args.reviewRunId },
      conclusion: { enum: ['pass', 'findings'] },
      note: nonBlankString,
      findings: { type: 'array', items: finding },
      readManifest,
      readLog,
      readDiagnostics: {
        type: 'array',
        items: {
          type: 'object',
          additionalProperties: false,
          required: ['code', 'severity', 'message'],
          properties: {
            code: { enum: [
              'read_manifest_missing_full_read',
              'read_manifest_extra_full_read',
              'read_manifest_missing_triage',
              'read_manifest_extra_triage',
              'full_scan_without_scanEscalationReason',
            ] },
            severity: { const: 'finding' },
            message: nonBlankString,
            path: nonBlankString,
          },
        },
      },
    },
    // Claude Code forwards this raw provider input_schema, whose top level
    // rejects oneOf/allOf/anyOf. Keep provider-facing common shape constraints
    // flat; the unchanged local parser remains authoritative for conclusion-
    // specific note/findings presence, exclusivity, and non-empty semantics.
  };
  const encoded = JSON.stringify(schema);
  if (Buffer.byteLength(encoded, 'utf8') > MANAGED_REVIEW_CLAUDE_JSON_SCHEMA_MAX_BYTES) {
    throw new Error(`host_run: managed Claude JSON Schema exceeds ${MANAGED_REVIEW_CLAUDE_JSON_SCHEMA_MAX_BYTES} bytes`);
  }
  return encoded;
}

export type ManagedReviewFinalEnvelopeClassification =
  | { kind: 'ordinary' }
  | { kind: 'malformed' }
  | { kind: 'valid'; envelope: ManagedReviewFinalEnvelopeRecord };

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every(item => typeof item === 'string');
}

/** Shared strict validator consumed at adapter, persistence, and import/gate boundaries. */
export function isStrictManagedReviewFindingProposal(value: unknown): value is ManagedReviewFinalEnvelopeFinding {
  if (!isPlainRecord(value)) return false;
  const allowed = new Set(['desc', 'severity', 'category', 'files', 'evidenceState', 'uncertaintyReason']);
  if (Object.keys(value).some(key => !allowed.has(key))) return false;
  if (typeof value.desc !== 'string' || value.desc.trim().length === 0) return false;
  if (!['critical', 'high', 'medium', 'low'].includes(String(value.severity))) return false;
  if (!['happy', 'edge', 'adversarial', 'missing'].includes(String(value.category))) return false;
  if (value.files !== undefined
    && (!isStringArray(value.files) || value.files.some(file => file.trim().length === 0))) return false;
  if (value.evidenceState !== undefined
    && value.evidenceState !== 'suspected'
    && value.evidenceState !== 'verified') return false;
  if (value.evidenceState === 'suspected') {
    if (typeof value.uncertaintyReason !== 'string' || value.uncertaintyReason.trim().length === 0) return false;
  } else if (value.uncertaintyReason !== undefined) {
    return false;
  }
  return true;
}

/**
 * Classify one provider-owned final assistant text without treating ordinary
 * Codex progress messages as proposal candidates. A message that explicitly
 * names the managed proposal schema remains fail-closed when malformed; valid
 * envelopes receive a second semantic/provenance validation in the managed
 * worker before any immutable proposal is written.
 */
export function classifyManagedReviewFinalEnvelope(text: string): ManagedReviewFinalEnvelopeClassification {
  const trimmed = text.trim();
  let parsed: unknown;
  try {
    parsed = JSON.parse(trimmed);
  } catch {
    return trimmed.includes(MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION)
      ? { kind: 'malformed' }
      : { kind: 'ordinary' };
  }
  if (!isPlainRecord(parsed)) return { kind: 'ordinary' };
  if (parsed.schemaVersion !== MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION) {
    return trimmed.includes(MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION)
      ? { kind: 'malformed' }
      : { kind: 'ordinary' };
  }

  const conclusion = parsed.conclusion;
  const allowed = new Set([
    'schemaVersion', 'storyId', 'providerAgent', 'lane', 'reviewRunId', 'conclusion',
    'readManifest', 'readLog', 'readDiagnostics', 'note', 'findings',
  ]);
  const readManifest = parsed.readManifest;
  const validReadManifest = isPlainRecord(readManifest)
    && isStringArray(readManifest.filesReadFully)
    && isStringArray(readManifest.filesTriagedByName)
    && (readManifest.scanEscalationReason === null || typeof readManifest.scanEscalationReason === 'string')
    && (readManifest.candidateSpecSetDigest === undefined || typeof readManifest.candidateSpecSetDigest === 'string')
    && (readManifest.corpusDigest === undefined || typeof readManifest.corpusDigest === 'string');
  const validConclusionPayload = conclusion === 'pass'
    ? typeof parsed.note === 'string'
      && parsed.note.trim().length > 0
      && (parsed.findings === undefined || (Array.isArray(parsed.findings) && parsed.findings.length === 0))
    : conclusion === 'findings'
      && Array.isArray(parsed.findings)
      && parsed.findings.length > 0
      && parsed.findings.every(isStrictManagedReviewFindingProposal)
      && (parsed.note === undefined || (typeof parsed.note === 'string' && parsed.note.trim().length > 0));
  if (Object.keys(parsed).some(key => !allowed.has(key))
    || typeof parsed.storyId !== 'string'
    || typeof parsed.providerAgent !== 'string'
    || typeof parsed.lane !== 'string'
    || typeof parsed.reviewRunId !== 'string'
    || !validReadManifest
    || !validConclusionPayload
    || (parsed.readLog !== undefined && !isPlainRecord(parsed.readLog))
    || (parsed.readDiagnostics !== undefined && !Array.isArray(parsed.readDiagnostics))) {
    return { kind: 'malformed' };
  }
  return { kind: 'valid', envelope: parsed as ManagedReviewFinalEnvelopeRecord };
}

