   try {
     writeFileSync(paths[0], JSON.stringify(hostAVerdict, null, 2) + '\n', 'utf8');
     writeFileSync(paths[1], JSON.stringify(hostBVerdict, null, 2) + '\n', 'utf8');
   } catch (err) {
     for (const path of paths) rmSync(path, { force: true });
     throw err;
   }
