 function deleteCrossHostVerdictPair(ctx: HandlerContext, storyId: string, ...verdicts: HostVerdict[]): void {
   const dir = join(ctx.root, LATTICE_DIR, 'autopilot-verdicts', storyId);
   for (const verdict of verdicts) {
