export const CROSS_HOST_REVIEW_DEFAULT_TIMEOUT_MINUTES = 12;

export function boundedCrossHostReviewTimeoutMinutes(
  requestedMinutes: number | undefined,
  policyMaxMinutes: number,
): number {
